fn evaluate_str(s: Str) -> Int {
  // Handle multiplication first (precedence): find * and /
  // Then handle addition
  // Simple implementation for "a + b * c" pattern:
  if s.contains("*") {
    let parts = s.split('+');
    var result = 0;
    for part in parts {
      let trimmed = part.trim();
      if trimmed.contains("*") {
        let mul_parts = trimmed.split('*');
        var prod = 1;
        for mp in mul_parts {
          prod = prod * mp.trim().parse_int().unwrap();
        }
        result = result + prod;
      } else {
        result = result + trimmed.parse_int().unwrap();
      }
    }
    return result;
  }
  return s.parse_int().unwrap();
}

fn main() -> Int {
  return evaluate_str("1 + 2 * 3");
}
